'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const answers={4:'voll und ganz',3:'weitgehend',2:'weniger',1:'gar nicht'};
const dims=['Selbststeuerung','Offline-Zeit','Nachrichtenüberfluss','FOMO','Bewusste Regulation','Überforderung','Schlaf'];
const symbols=['①','②','③','④','⑤','⑥','⑦'];
const defaultWeeks=['Ferien','Ferien','Schule I','Praktikum','Praktikum / Übergang','Schule II'];
let boot, polling, expiryTimer, currentClass, currentResponse, step=0, saveTimer, saveQueue=Promise.resolve(), generation=0, detail=false, appMode='cloud', busy=false;
const mem=new Map();
function storage(type,key,value){try{const s=type==='local'?localStorage:sessionStorage;if(value===undefined)return JSON.parse(s.getItem(key)||'null');if(value===null)s.removeItem(key);else s.setItem(key,JSON.stringify(value));}catch{if(value===undefined)return mem.get(key)||null;if(value===null)mem.delete(key);else mem.set(key,value);}}
function saved(code){const v=storage('local','handy:'+code);return v||null;}
function remember(code,token,expires_at){storage('local','handy:'+code,{token,expires_at,step});}
const params=()=>new URLSearchParams(location.search), view=()=>params().get('view')||(params().has('code')?'join':'home'), code=()=>params().get('code')||'';
function adminToken(){return storage('session','handy-admin')?.token||'';}
function ownToken(){return saved(code())?.token||'';}
function notice(text,error=false){const el=$('#notice');el.textContent=text;el.className='visible'+(error?' error':'');clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.className='',error?8500:4000);}
async function api(route,{data,token,code:classCode}={}){
 const url=new URL('api.php',location.href);url.searchParams.set('r',route);if(classCode)url.searchParams.set('code',classCode);
 const headers={};if(token)headers.Authorization='Bearer '+token;
 if(data!==undefined){headers['Content-Type']='application/json';headers['X-CSRF-Token']=boot.csrf;}
 const res=await fetch(url,{method:data!==undefined?'POST':'GET',headers,body:data!==undefined?JSON.stringify(data):undefined,cache:'no-store',credentials:'same-origin'});
 let result;try{result=await res.json();}catch{throw new Error('Der Server ist nicht erreichbar. Deine Eingaben bleiben auf dieser Seite erhalten.');}
 if(!res.ok){const e=new Error(result.error||'Die Anfrage ist fehlgeschlagen.');e.status=res.status;throw e;}return result;
}
function go(v,c=''){clearTimeout(saveTimer);history.pushState({},'',`?view=${v}${c?'&code='+encodeURIComponent(c):''}`);render();}
function setMain(html){$('#main').innerHTML=html;$('#main').focus({preventScroll:true});}
function link(v,label,cls='button secondary',c=''){return `<a class="${cls}" href="?view=${v}${c?'&code='+encodeURIComponent(c):''}">${label}</a>`;}
function process(){return '<div class="process-strip"><span>BEOBACHTEN</span><b>›</b><span>ICH</span><b>›</b><span>WIR</span><b>›</b><span>JIM</span><b>›</b><span>REFLEKTIEREN</span><b>›</b><span>GESTALTEN</span></div>';}
const fmt=n=>n===null||n===undefined?'–':new Intl.NumberFormat('de-DE',{maximumFractionDigits:1}).format(n);
const date=x=>new Date(x).toLocaleString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
const avg=a=>{const b=a.filter(v=>v!==null);return b.length?b.reduce((s,v)=>s+Number(v),0)/b.length:null;};
function expire(){clearInterval(polling);clearInterval(expiryTimer);clearTimeout(saveTimer);if(code())storage('local','handy:'+code(),null);storage('session','handy-admin',null);currentResponse=null;currentClass=null;setMain(`<div class="narrow empty"><h1>Diese Runde ist beendet.</h1><p>Die Klasse ist abgelaufen oder wurde gelöscht. Ihre Daten sind nicht mehr verfügbar.</p><p class="help">Du kannst eine neue Runde beginnen.</p>${link('home','Zur Startseite')}</div>`);}
function watchClass(c){currentClass=c;clearInterval(expiryTimer);const tick=()=>{const left=Date.parse(c.expires_at)-Date.now();if(left<=0){clearInterval(expiryTimer);api('class',{code:c.code}).then(r=>watchClass(r.class)).catch(e=>{if(e.status===410||e.status===404)expire();else{notice('Ablaufzeit konnte nicht geprüft werden. Bitte erneut laden.',true);}});return;}$$('[data-remaining]').forEach(e=>e.textContent=left>86400000?Math.ceil(left/86400000)+' Tage':Math.floor(left/3600000)+' Std. '+Math.ceil((left%3600000)/60000)+' Min.');};tick();expiryTimer=setInterval(tick,1000);const s=saved(c.code);if(s)remember(c.code,s.token,c.expires_at);}
async function render(){
 clearInterval(polling);clearInterval(expiryTimer);document.body.classList.remove('present');const gen=++generation;
 try{
 switch(view()){
 case 'home':home();break;
 case 'create':createPage();break;
 case 'info':infoPage();break;
 case 'privacy':privacyPage();break;
 case 'projects':projectPage();break;
 case 'join':await joinPage(gen);break;
 case 'survey':await surveyPage(gen);break;
 case 'result':case 'admin':case 'class':await resultPage(gen);break;
 default:go('home');
 }
 }catch(e){if(gen!==generation)return;if(e.status===410){expire();return;}setMain(`<div class="narrow empty"><h1>Ein Moment bitte.</h1><p>${esc(e.message)}</p><div class="actions" style="justify-content:center;margin-top:22px"><button class="button" id="retry">Erneut versuchen</button>${link('home','Zur Startseite')}</div></div>`);$('#retry').onclick=render;}
}
function homeStudies(studies){if(!studies)return '';const q=studies.quote;return `<section class="study-section" aria-labelledby="study-heading"><div class="study-heading"><div><p class="eyebrow">Ein Blick in die Forschung</p><h2 id="study-heading">Mehr als Bildschirmzeit.</h2></div><p>Was digitale Medien im Alltag bedeuten,<br>hat viele Seiten. JIMplus gibt Einblicke.</p></div><figure class="study-quote"><span class="quote-symbol" aria-hidden="true">“</span><div><figcaption>ORIGINALTON · MPFS</figcaption><blockquote>„… ${esc(q.text)}“</blockquote><a href="${esc(q.source)}" target="_blank" rel="noopener noreferrer">${esc(q.attribution)} ↗</a></div><div class="quote-art" aria-hidden="true"><span>entdecken</span><span>hinterfragen</span><span>verstehen</span></div></figure><div class="study-grid">${studies.charts.map(c=>`<figure class="study-card"><figcaption><span class="study-tag">${esc(c.study)}</span><h3>${esc(c.title)}</h3><p>${esc(c.intro)}</p></figcaption><div class="study-chart ${c.kind==='dots'?'study-dot-chart':''}">${c.values.map(v=>`<div class="study-value"><div class="study-value-label"><span>${esc(v.label)}</span><strong>${fmt(v.value)}<small> %</small></strong></div>${c.kind==='dots'?`<div class="study-dots" aria-hidden="true">${Array.from({length:100},(_,i)=>`<i class="${i<v.value?'filled':''}"></i>`).join('')}</div>`:`<div class="study-track" aria-hidden="true"><span style="width:${Math.max(0,Math.min(100,Number(v.value)))}%"></span></div>`}</div>`).join('')}${c.kind==='bars'?'<div class="study-scale" aria-hidden="true"><span>0 %</span><span>50 %</span><span>100 %</span></div>':'<p class="help">Jeder Punkt steht für einen Prozentpunkt.</p>'}</div><p class="study-basis">${esc(c.basis)}</p><p class="study-note">${esc(c.note)}</p><a class="study-source" href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">${esc(c.source_label)} ↗</a></figure>`).join('')}</div><div class="study-takeaway"><div><p class="eyebrow">Zum Weiterdenken</p><h3>Welche Rolle spielt dein Handy in deinem Alltag?</h3><p>Die Studie zeigt Erfahrungen anderer Jugendlicher. Mit Medienblick beobachtest du deinen eigenen Alltag: Wann nutzt du dein Handy, was ist dir dabei wichtig und wie erlebst du diese Zeit? Dein privates Protokollheft ist die Grundlage für deinen eigenen Blick.</p><p class="help">Reflexionsfragen von Medienblick · keine Aussagen aus der Studie.</p></div>${link('info','So funktioniert Medienblick →','button secondary')}</div><p class="study-credit">Eigene Grafiken auf Basis der Originaldaten des Medienpädagogischen Forschungsverbunds Südwest (mpfs). Die Befunde beziehen sich auf Social Media und auf 14–17-Jährige, nicht auf jede Form der Handynutzung. ${link('info','So funktioniert das Handy-Experiment →')}</p></section>`;}
function home(){setMain(`<div class="home-top"><section class="home-intro"><p class="eyebrow">Medienblick · Mein Handy-Experiment</p><h1>Dein Handy.<br><span>Dein Blick.</span></h1><p class="lead">Du hast deinen Medienalltag beobachtet. Jetzt ordnest du deine Erfahrungen ein – für dich und gemeinsam mit deiner Klasse.</p><p class="help">Nimm dein Protokollheft zur Hand.<br>Deine täglichen Antworten bleiben bei dir.</p></section><section class="join-panel"><p class="eyebrow" style="color:#fecdd3">Nach eurer Beobachtungszeit</p><h2>Deine Auswertung beginnt hier.</h2><form id="join-form"><label for="code-input">Klassencode</label><input id="code-input" name="code" maxlength="6" minlength="6" placeholder="K7M4PX" autocomplete="off" autocapitalize="characters" spellcheck="false" required pattern="[A-Za-z2-9]{6}"><button class="button">Zur Klasse</button></form><p class="help" style="margin:14px 0 0">Anonym · freiwillig · ohne Schülerkonto</p><div class="teacher-start"><span class="small-title">Du bist Lehrkraft?</span>${link('create','Neue Klasse erstellen','')}</div></section></div>${homeStudies(boot.home_insights)}`);$('#join-form').onsubmit=e=>{e.preventDefault();go('join',$('#code-input').value.trim().toUpperCase());};}
const weekTypes={ferien:'Ferien',schule:'Schule',praktikum:'Praktikum',sonstiges:'Sonstiges'};
function defaultWeek(i){return {context_type:i<2?'ferien':i===3||i===4?'praktikum':'schule',label:defaultWeeks[i]||'Schule',start_date:'',end_date:''};}
function createPage(){
 let weeks=Array.from({length:6},(_,i)=>defaultWeek(i));
 const capture=()=>$$('.week-edit').forEach((el,i)=>{weeks[i]={context_type:$('[data-type]',el).value,label:$('[data-label]',el).value,start_date:$('[data-start]',el).value,end_date:$('[data-end]',el).value};});
 setMain(`<div class="narrow">${link('home','Zurück','back-link')}<p class="eyebrow">Für Lehrkräfte</p><h1>Euer Zeitraum.<br>Eure Perspektiven.</h1><p class="lead">Sechs Wochen sind der Standard. Lege die Dauer und die Wochenarten passend zu eurem Projekt fest.</p><p class="help">Erstelle die Klasseninstanz erst für die gemeinsame Auswertung nach der Beobachtungszeit. Sie bleibt zunächst 270 Minuten aktiv.</p><form id="create-form" class="card stack"><div class="grid2"><div><label for="class-label">Klassenbezeichnung (optional)</label><input id="class-label" maxlength="40" placeholder="z. B. 9b"><p class="help">Bitte keine Namen und keine Schule angeben.</p></div><div><label for="age">JIM-Vergleichsalter</label><select id="age"><option value="12-13">12–13 Jahre</option><option value="14-15" selected>14–15 Jahre</option><option value="16-17">16–17 Jahre</option><option value="18-19">18–19 Jahre</option></select></div></div><div><label for="expected">Erwartete Teilnehmerzahl (optional)</label><input id="expected" type="number" min="1" max="500" placeholder="z. B. 24"></div><div><label for="week-count">Beobachtungsdauer in Wochen</label><input id="week-count" type="number" min="1" max="52" step="1" value="6" required ${boot.flexible_weeks?'':'disabled'}><p class="help">Standard: 6 Wochen · möglich: 1 bis 52 Wochen. Jede der sieben Reflexionsfragen wird einmal pro Woche beobachtet.</p>${boot.flexible_weeks?'':'<p class="banner">Andere Zeiträume werden nach dem Datenbankupdate durch den Betreiber verfügbar.</p>'}<h2>Eure Wochen</h2><p class="help">Wähle für jede Woche eine Art. Eine eigene Bezeichnung und Kalenderdaten sind optional. Vorhandene Eingaben bleiben beim Ändern der Wochenzahl in diesem Formular erhalten.</p><div id="week-editors" class="weeks-grid"></div></div><p class="help">Die Beobachtungsdauer ist unabhängig von der Speicherfrist: Ohne Verlängerung wird die Klasseninstanz nach 4 Stunden und 30 Minuten gelöscht. Mit Lehrkräfteschlüssel maximal 28 Tage. Dauer und Wochenarten werden mit dem Erstellen festgelegt.</p><button class="button" type="submit">Klasse erstellen</button></form></div>`);
 const draw=()=>{
  const count=Number($('#week-count').value);
  if(!Number.isInteger(count)||count<1||count>52)return;
  for(let i=weeks.length;i<count;i++)weeks.push(defaultWeek(i));
  $('#week-editors').innerHTML=weeks.slice(0,count).map((w,i)=>`<div class="week-edit"><h3>Woche ${i+1}</h3><label for="type-${i}">Wochenart</label><select id="type-${i}" data-type>${Object.entries(weekTypes).map(([k,v])=>`<option value="${k}" ${w.context_type===k?'selected':''}>${v}</option>`).join('')}</select><label for="week-${i}">Eigene Bezeichnung (optional)</label><input id="week-${i}" data-label value="${esc(w.label)}" maxlength="60" placeholder="z. B. Klassenfahrt"><details><summary class="help">Kalenderdaten ergänzen</summary><div class="grid2"><div><label for="start-${i}">Beginn</label><input id="start-${i}" data-start type="date" value="${esc(w.start_date)}"></div><div><label for="end-${i}">Ende</label><input id="end-${i}" data-end type="date" value="${esc(w.end_date)}"></div></div></details></div>`).join('');
  $$('[data-type]').forEach(el=>el.onchange=()=>{const i=Number(el.id.split('-')[1]),label=$('#week-'+i);if(!label.value||label.value===weeks[i].label&&[...Object.values(weekTypes),...defaultWeeks].includes(label.value))label.value=weekTypes[el.value];capture();});
 };
 draw();$('#week-count').onchange=()=>{capture();draw();};
 $('#create-form').onsubmit=async e=>{e.preventDefault();capture();await action(async()=>{const count=Number($('#week-count').value);const data={label:$('#class-label').value,age_group:$('#age').value,expected:$('#expected').value?Number($('#expected').value):null,weeks:weeks.slice(0,count).map(w=>({...w,label:w.label.trim()||weekTypes[w.context_type],start_date:w.start_date||null,end_date:w.end_date||null}))};const result=await api('classes',{data});storage('session','handy-admin',{token:result.admin_token});go('admin',result.class.code);},e.submitter);};
}
async function joinPage(gen){const r=await api('class',{code:code()});if(gen!==generation)return;watchClass(r.class);const s=saved(code());setMain(`<div class="narrow">${link('home','Zurück','back-link')}<p class="eyebrow">Klasse ${esc(r.class.label||r.class.code)}</p><h1>Dein Heft bleibt privat.<br>Deine Sicht zählt.</h1><div class="card"><p><strong>${r.class.n} abgeschlossene Teilnahmen</strong> · Noch <span data-remaining></span></p><p>Schau bei jeder Aussage auf die zugehörigen Antworten aus euren ${r.class.weeks.length} Beobachtungswochen in deinem Heft. Entscheide dann selbst, wie sie insgesamt auf dich zutrifft.</p><ul><li>Keine täglichen Rohdaten nachtragen.</li><li>Keine Namen, E-Mail-Adressen oder Schülerkonten.</li><li>Deine Lehrkraft sieht nur Klassenstatistiken.</li><li>Die Teilnahme ist freiwillig. Du kannst vor der Abgabe jederzeit aufhören.</li></ul><p class="help">Ein zufälliger Zugangsschlüssel wird auf diesem Gerät gespeichert, damit du fortsetzen und dein Ergebnis ansehen kannst. Auf gemeinsam genutzten Geräten anschließend „Zugang auf diesem Gerät entfernen“ wählen. Löschung der Klasse: ${date(r.class.expires_at)}.</p>${s?'<div class="banner">Du hast bereits mit deiner Auswertung begonnen.</div>':''}<button class="button" id="start">${s?'Auswertung fortsetzen':'Auswertung starten'}</button><p class="help" style="margin-top:16px;margin-bottom:0">${link('privacy','Mehr zum Datenschutz','')}</p></div></div>`);watchClass(r.class);$('#start').onclick=e=>action(async()=>{if(!s){const a=await api('start',{data:{},code:code()});step=0;remember(code(),a.token,a.class.expires_at);}go('survey',code());},e.currentTarget);}
async function surveyPage(gen){const t=ownToken();if(!t){go('join',code());return;}const r=await api('response',{token:t});if(gen!==generation)return;if(r.response.status==='submitted'){go('result',r.class.code);return;}currentResponse=r.response;currentClass=r.class;step=Math.min(10,Math.max(0,saved(code())?.step||0));watchClass(r.class);showStep();}
function payload(){return {items:currentResponse.items,screen:currentResponse.screen,apps:currentResponse.apps,reflection:currentResponse.reflection};}
function enqueueSave(){const data=JSON.parse(JSON.stringify(payload())),t=ownToken(),g=generation;saveQueue=saveQueue.catch(()=>{}).then(()=>api('draft',{data,token:t}));saveQueue.then(()=>{if(g===generation&&$('#save-state'))$('#save-state').textContent='Entwurf gespeichert';},e=>{if(g===generation){if(e.status===410)expire();else{if($('#save-state'))$('#save-state').textContent='Noch nicht gespeichert – bitte erneut versuchen';notice(e.message,true);}}});return saveQueue;}
function debounceSave(){clearTimeout(saveTimer);if($('#save-state'))$('#save-state').textContent='Wird gespeichert …';saveTimer=setTimeout(enqueueSave,700);}
function storeStep(){const s=saved(code());if(s)remember(code(),s.token,currentClass.expires_at);}
function showStep(){
 storeStep();let content='';const r=currentResponse;
 if(step<7){content=`<p class="eyebrow">${symbols[step]} ${dims[step]}</p><div class="heft-hint">Schau dir im Protokollheft deine <strong>Antworten zu ${symbols[step]} aus euren ${currentClass.weeks.length} Beobachtungswochen</strong> an. Nutze sie als Grundlage für deine Gesamteinschätzung.</div><p class="help">Wenn du auf die vergangenen ${currentClass.weeks.length} Beobachtungswochen zurückblickst:</p><h1 class="question">${esc(boot.items[step][1])}</h1><div class="options" role="group" aria-label="Deine Antwort">${[4,3,2,1].map(v=>`<button class="option" data-answer="${v}" aria-pressed="${r.items[step]===v}">${answers[v]}</button>`).join('')}</div>`;}
 else if(step===7){content=`<p class="eyebrow">Bildschirmzeit</p><h1 class="question">Wie sah deine Beobachtungszeit aus?</h1><p>Trage pro Woche die durchschnittliche tägliche Smartphone-Bildschirmzeit ein – in Minuten.</p><p class="help">Fehlende Werte bitte leer lassen, nicht erfinden. 0 bedeutet tatsächlich keine Nutzung. Die Rechenhilfe nutzt nur vorhandene Tage und überträgt ausschließlich den Durchschnitt.</p>${currentClass.weeks.map((w,i)=>`<div class="week-row"><div class="week-head"><label for="screen-${i}">Woche ${i+1}<br><span class="help">${esc(w.label)}</span></label><div class="minute-input"><input id="screen-${i}" data-screen="${i}" type="number" min="0" max="1440" step="0.01" inputmode="decimal" placeholder="Minuten" value="${r.screen[i]??''}" aria-label="Woche ${i+1}: Minuten pro Tag"></div></div><details class="calculator" data-week="${i}"><summary class="help">Durchschnitt lokal berechnen</summary><div class="day-grid">${Array.from({length:7},(_,j)=>`<div><label for="day-${i}-${j}">Tag ${j+1}</label><input id="day-${i}-${j}" type="number" min="0" max="1440" inputmode="numeric" placeholder="Min." data-day></div>`).join('')}</div><p class="calc-result" aria-live="polite">Noch keine Tageswerte.</p><button class="button secondary small" data-use-average="${i}" type="button">Durchschnitt übernehmen</button><p class="help">Diese Tageswerte bleiben nur im Arbeitsspeicher dieses Browsers.</p></details></div>`).join('')}`;}
 else if(step===8){content=`<p class="eyebrow">Deine wichtigsten Apps</p><h1 class="question">Welche drei Apps waren für dich über die gesamte Beobachtungszeit insgesamt am wichtigsten?</h1><p>Wichtig heißt nicht automatisch: am längsten genutzt. Du kannst bis zu drei Apps nennen oder die Felder frei lassen.</p><div class="stack">${[0,1,2].map(i=>`<div><label for="app-${i}">App ${i+1} (optional)</label><input id="app-${i}" data-app="${i}" maxlength="60" list="app-options" autocomplete="off" placeholder="App eingeben oder auswählen" value="${esc(r.apps[i]||'')}"></div>`).join('')}</div><datalist id="app-options">${boot.apps.map(a=>`<option value="${esc(a)}">`).join('')}</datalist><p class="help" style="margin-top:18px">Auch andere Apps sind möglich. Bitte nur App-Namen nennen, keine Personen oder privaten Inhalte. Unbekannte Begriffe erscheinen erst nach Freigabe in der Klassenansicht.</p>`;}
 else if(step===9){content=`<p class="eyebrow">Ein Gedanke zum Schluss</p><h1 class="question">Was hat dich an deiner eigenen Handynutzung am meisten überrascht?</h1><label for="reflection">Deine Reflexion (freiwillig)</label><textarea id="reflection" maxlength="2000" placeholder="Wenn du möchtest, halte hier deinen Gedanken fest.">${esc(r.reflection)}</textarea><p class="help">Nicht Teil von JIM. Dieser Text bleibt in deiner persönlichen Ansicht und erscheint weder bei der Lehrkraft noch am Smartboard. Bitte keine Namen eintragen.</p>`;}
 else{content=`<p class="eyebrow">Vor der Abgabe</p><h1 class="question">Passt das für dich?</h1><p>Prüfe deine Gesamteinschätzung. Nach der Abgabe bleibt dein ICH unverändert.</p><div class="summary-list">${r.items.map((v,i)=>`<div class="summary-line"><span>${symbols[i]} ${esc(boot.items[i][1])}</span><strong>${answers[v]||'Noch nicht beantwortet'}</strong><button class="button secondary small" data-edit="${i}">Ändern</button></div>`).join('')}<div class="summary-line"><span>Bildschirmzeit · Minuten pro Tag</span><strong>${r.screen.map((v,i)=>`W${i+1}: ${fmt(v)}`).join(' · ')}</strong><p class="help">${r.screen.filter(v=>v!==null).length} von ${currentClass.weeks.length} Wochen vorhanden. Fehlende Wochen bleiben fehlend.</p><button class="button secondary small" data-edit="7">Ändern</button></div><div class="summary-line"><span>Wichtigste Apps</span><strong>${esc(r.apps.filter(Boolean).join(', ')||'Keine Nennung')}</strong><button class="button secondary small" data-edit="8">Ändern</button></div><div class="summary-line"><span>Private Reflexion</span><p>${esc(r.reflection||'Keine Angabe')}</p><button class="button secondary small" data-edit="9">Ändern</button></div></div><div class="banner" style="margin-top:22px">Nur die sieben Aussagen sind Pflicht. Vergessene Beobachtungen sollen nicht nachträglich erfunden werden.</div>`;}
 setMain(`<div class="narrow"><div class="progress-label"><span>${step<7?'Frage '+(step+1)+' von 7': ['Bildschirmzeit','Apps','Reflexion','Zusammenfassung'][step-7]}</span><span>ICH · ${Math.round((step+1)/11*100)} %</span></div><progress max="11" value="${step+1}" aria-label="Fortschritt"></progress><section class="card survey-card">${content}<div class="actions between" style="margin-top:28px"><button class="button secondary" id="previous">${step?'Zurück':'Später fortsetzen'}</button><button class="button" id="next">${step===10?'Auswertung abschicken':'Weiter'}</button></div><p class="help" id="save-state" role="status" style="margin:15px 0 0">Entwurf gespeichert</p></section></div>`);
 $$('[data-answer]').forEach(el=>el.onclick=()=>{r.items[step]=Number(el.dataset.answer);$$('[data-answer]').forEach(b=>b.setAttribute('aria-pressed',b===el));debounceSave();});
 $$('[data-screen]').forEach(el=>el.oninput=()=>{if(el.checkValidity()){r.screen[Number(el.dataset.screen)]=el.value===''?null:Number(el.value);debounceSave();}});
 $$('.calculator').forEach(calc=>{const calculate=()=>{const inputs=$$('[data-day]',calc);if(inputs.some(e=>!e.checkValidity()))return null;const v=inputs.filter(e=>e.value!=='').map(e=>Number(e.value));return v.length?{value:Math.round(avg(v)*100)/100,n:v.length}:null;};$$('[data-day]',calc).forEach(el=>el.oninput=()=>{const a=calculate();$('.calc-result',calc).textContent=a?`${fmt(a.value)} Minuten pro Tag · ${a.n} von 7 Tagen`:'Bitte gültige Minutenwerte eingeben.';});$('[data-use-average]',calc).onclick=()=>{const a=calculate();if(!a){notice('Bitte mindestens einen gültigen Tageswert eintragen.',true);return;}const i=Number(calc.dataset.week);r.screen[i]=a.value;$('#screen-'+i).value=a.value;debounceSave();notice('Nur der Wochendurchschnitt wird gespeichert.');};});
 $$('[data-app]').forEach(el=>el.oninput=()=>{r.apps=[0,1,2].map(i=>$('#app-'+i).value);debounceSave();});if($('#reflection'))$('#reflection').oninput=e=>{r.reflection=e.target.value;debounceSave();};
 $$('[data-edit]').forEach(el=>el.onclick=()=>{step=Number(el.dataset.edit);showStep();});
 $('#previous').onclick=e=>action(async()=>{clearTimeout(saveTimer);await enqueueSave();if(step>0){step--;showStep();}else go('join',code());},e.currentTarget);
 $('#next').onclick=e=>action(async()=>{if(step<7&&r.items[step]===null){notice('Bitte wähle eine Antwort.',true);return;}if(step===7){const invalid=$$('[data-screen]').find(e=>!e.checkValidity());if(invalid){invalid.reportValidity();return;}}clearTimeout(saveTimer);await enqueueSave();if(step===10){await api('submit',{data:payload(),token:ownToken()});go('result',code());}else{step++;showStep();window.scrollTo(0,0);}},e.currentTarget);
}
async function action(fn,button){if(busy)return;busy=true;if(button)button.disabled=true;try{await fn();}catch(e){if(e.status===410)expire();else notice(e.message,true);}finally{busy=false;if(button)button.disabled=false;}}
function refItem(jim,i){const id='jim_'+String(i+1).padStart(2,'0'),rows=jim.values.filter(r=>r.item_id===id),dist={};for(const r of rows)if(r.metric_type==='item_distribution')dist[r.response_value]=Number(r.percentage);const complete=[1,2,3,4].every(k=>dist[k]!==undefined);const agreement=rows.find(r=>r.metric_type==='item_agreement');return {age:rows[0]?.age_group||jim.age_group,dist:complete?dist:null,agreement:complete?dist[3]+dist[4]:agreement?Number(agreement.percentage):null};}
function distribution(d,selected){return `<div class="distribution" aria-hidden="true">${[4,3,2,1].map(k=>`<span class="${selected===k?'selected':''}" style="width:${Number(d[k])}%"></span>`).join('')}</div>`;}
function itemCard(i,data){const ownValue=data.response?.items[i],w=data.wir.available?data.wir.items[i]:null,j=refItem(data.jim,i);return `<section class="card"><div class="item-title"><span class="item-number">${i+1}</span><div><p class="eyebrow" style="margin-bottom:6px">${dims[i]}</p><h3>${esc(boot.items[i][1])}</h3></div></div><div class="compare-grid ${ownValue?'':'no-own'}">${ownValue?`<div class="compare-cell own"><span class="overline">ICH</span><strong>${answers[ownValue]}</strong></div>`:''}<div class="compare-cell class"><span class="overline">WIR</span><strong>${w?fmt(w.agreement)+' %':'Noch nicht verfügbar'}</strong><p class="help">${w?'stimmen voll und ganz / weitgehend zu':'ab fünf vollständigen Abgaben'}</p>${w?distribution(w.percent,ownValue):''}</div><div class="compare-cell ref"><span class="overline">JIM ${data.jim.dataset.study_year} · ${esc(j.age)} Jahre${j.age==='12-19'?' · Gesamtgruppe':''}</span><strong>${j.agreement===null?'Kein Referenzwert':fmt(j.agreement)+' %'}</strong><p class="help">${j.agreement===null?'Für diesen Vergleich liegt noch kein Referenzwert vor.':'stimmen voll und ganz / weitgehend zu'+(j.age==='12-19'?'. Gesamtwert; keine eigene Altersauswertung.':'')}</p>${j.dist?distribution(j.dist,ownValue):''}</div></div><div class="detail-view table-scroll" ${detail?'':'hidden'}><table><caption class="help">Vier Antwortkategorien${ownValue?' · eigene Antwort hervorgehoben':''}</caption><thead><tr><th>Antwort</th><th>WIR · Anzahl</th><th>WIR · %</th><th>JIM · %</th></tr></thead><tbody>${[4,3,2,1].map(k=>`<tr><td class="${ownValue===k?'marked':''}">${answers[k]}${ownValue===k?' (ICH)':''}</td><td>${w?w.counts[k]:'–'}</td><td>${w?fmt(w.percent[k]):'–'}</td><td>${j.dist?fmt(j.dist[k]):'–'}</td></tr>`).join('')}</tbody></table>${!j.dist?'<p class="help">Eine vollständige JIM-Viererverteilung ist für dieses Item nicht hinterlegt.</p>':''}</div></section>`;}
function lineChart(ownValues,weeks){const valid=[...(ownValues||[]),...weeks.map(w=>w?.mean??null)].filter(x=>x!==null);if(!valid.length)return '<p class="help">Noch keine darstellbaren Wochenwerte.</p>';const max=Math.max(60,Math.ceil(Math.max(...valid)/60)*60),x=i=>weeks.length===1?310:48+i*520/(weeks.length-1),y=v=>205-v/max*170;const series=(values,color,dash='')=>{let out='';for(let i=0;i<values.length-1;i++)if(values[i]!==null&&values[i+1]!==null)out+=`<line x1="${x(i)}" y1="${y(values[i])}" x2="${x(i+1)}" y2="${y(values[i+1])}" stroke="${color}" stroke-width="3" ${dash}/>`;values.forEach((v,i)=>{if(v!==null)out+=`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="${color}"/>`;});return out;};return `<svg class="chart" viewBox="0 0 620 235" role="img" aria-label="Verlauf der durchschnittlichen täglichen Bildschirmzeit. Alle Werte stehen auch in der Tabelle.">${[0,.25,.5,.75,1].map(f=>`<line x1="48" y1="${y(max*f)}" x2="585" y2="${y(max*f)}" stroke="#dce4e8"/><text x="38" y="${y(max*f)+4}" text-anchor="end">${Math.round(max*f)}</text>`).join('')}${series(weeks.map(w=>w?.mean??null),'#63314c')}${ownValues?series(ownValues,'#9f1239','stroke-dasharray="6 4"'):''}${weeks.map((_,i)=>i%Math.max(1,Math.ceil(weeks.length/12))===0||i===weeks.length-1?`<text x="${x(i)}" y="228" text-anchor="middle">W${i+1}</text>`:'').join('')}</svg>`;}
function screenCard(data){const s=data.wir.available?data.wir.screen:{weeks:Array(data.class.weeks.length).fill(null),overall:null,contexts:[]},ownValues=data.response?.screen,ownMean=ownValues?avg(ownValues):null,j=data.jim.values.find(r=>r.metric_type==='screen_mean'&&r.item_id==='smartphone_minutes');return `<section class="card screen-card"><p class="eyebrow">Bildschirmzeit</p><h2>Alltag verändert Nutzung.</h2><p class="help">Durchschnittliche tägliche Smartphone-Bildschirmzeit in Minuten.</p><div class="compare-grid ${ownValues?'':'no-own'}">${ownValues?`<div class="compare-cell own"><span class="overline">ICH</span><strong>${fmt(ownMean)} Min.</strong></div>`:''}<div class="compare-cell class"><span class="overline">WIR</span><strong>${fmt(s.overall?.mean)} Min.</strong><p class="help">Median: ${fmt(s.overall?.median)} Min. · n = ${s.overall?.n??'unter 5'}</p></div><div class="compare-cell ref"><span class="overline">JIM ${data.jim.dataset.study_year} · ${esc(j?.age_group||data.jim.age_group)} Jahre</span><strong>${j?fmt(Number(j.numeric_value))+' Min.':'Kein Referenzwert'}</strong><p class="help">${j?'Am Smartphone abgelesene Zeit (Basis insgesamt n = 960). Andere Zeitbasis als euer Wochenmittel; kein Grenzwert.':'Kein verifizierter Wert zur Smartphone-Bildschirmzeit dieser Altersgruppe hinterlegt.'}</p></div></div>${ownMean!==null&&s.overall?`<p class="help" style="margin-top:15px">Dein Ergebnis liegt ${fmt(Math.abs(ownMean-s.overall.mean))} Minuten ${ownMean>=s.overall.mean?'über':'unter'} dem aktuellen Klassenmittel.</p>`:''}<h3 style="margin-top:28px">Eure ${data.class.weeks.length} Beobachtungswochen</h3>${lineChart(ownValues,s.weeks)}<div class="chart-labels">${data.class.weeks.map(w=>`<div><strong>W${w.week_number}</strong>${esc(w.label)}</div>`).join('')}</div><p class="help">${ownValues?'Gestrichelt / Rot: ICH · ':''}Durchgezogen / Dunkelrot: WIR. Lücken bleiben Lücken.</p><details><summary class="help">Werte als Tabelle ansehen</summary><div class="screen-table table-scroll"><table><thead><tr><th>Woche / Kontext</th>${ownValues?'<th>ICH</th>':''}<th>WIR Mittel</th><th>Median</th><th>n</th></tr></thead><tbody>${data.class.weeks.map((w,i)=>`<tr><td>${i+1} · ${esc(w.label)}</td>${ownValues?`<td>${fmt(ownValues[i])}</td>`:''}<td>${fmt(s.weeks[i]?.mean)}</td><td>${fmt(s.weeks[i]?.median)}</td><td>${s.weeks[i]?.n??'unter 5'}</td></tr>`).join('')}</tbody></table></div></details><h3 style="margin-top:24px">Kontexte im Vergleich</h3><div class="table-scroll"><table><thead><tr><th>Kontext</th><th>WIR Mittel</th><th>Median</th><th>n</th></tr></thead><tbody>${s.contexts.length?s.contexts.map(c=>`<tr><td>${esc(c.label)}</td><td>${fmt(c.stats?.mean)}</td><td>${fmt(c.stats?.median)}</td><td>${c.stats?.n??'unter 5'}</td></tr>`).join(''):'<tr><td colspan="4">Sichtbar ab fünf vollständigen Abgaben.</td></tr>'}</tbody></table></div><p class="help" style="margin:18px 0 0">Gesamtmittel und Median beziehen sich auf die persönlichen Mittelwerte vorhandener Wochen. Bei gleicher Wochenart werden Wochen zunächst pro Person zusammengefasst. Fehlende Angaben sind keine Nullwerte. Jede Statistik benötigt mindestens fünf Werte.</p></section>`;}
function appTable(apps){return `<table class="print-app-table"><thead><tr><th>App</th><th>Nennungen</th><th>Anteil der Klasse</th></tr></thead><tbody>${apps.map(a=>`<tr><td>${esc(a.name)}</td><td>${a.count}</td><td>${fmt(a.percentage)} %</td></tr>`).join('')}</tbody></table>`;}
function appsView(data){if(!data.wir.available)return '<p class="help">App-Ergebnisse erscheinen ab fünf vollständigen Abgaben.</p>';const apps=data.wir.apps;if(!apps.length)return '<p class="help">Noch keine freigegebenen App-Nennungen vorhanden.</p>';if(appMode==='rank')return appTable(apps);if(appMode==='bars')return apps.map(a=>`<div class="bar-row"><strong>${esc(a.name)}</strong><div class="bar-track"><div class="bar-fill" style="width:${a.percentage}%"></div></div><span>${a.count} · ${fmt(a.percentage)} %</span></div>`).join('');const max=Math.max(...apps.map(a=>a.count));return `<div class="cloud" aria-label="App-Wortwolke, Größe nach Häufigkeit">${apps.map(a=>`<span style="font-size:${Math.round(16+28*a.count/max)}px" title="${a.count} Nennungen · ${fmt(a.percentage)} %">${esc(a.name)}<span class="help"> (${a.count})</span></span>`).join('')}</div>`;}
function appsCard(data){const refs=data.jim.values.filter(r=>r.metric_type==='app_percentage');return `<section class="card"><p class="eyebrow">Wichtigste Apps</p><h2>Was euch wichtig war.</h2>${data.response?`<p><span class="badge ich">ICH</span> ${esc(data.response.apps.join(', ')||'Keine Nennung')}</p>`:''}<p class="help">Bis zu drei Nennungen pro Person. Anteile beziehen sich auf alle ${data.wir.n} Abgaben; zusammen können sie über 100 % liegen.</p><div class="tabs no-print" aria-label="App-Darstellung">${[['cloud','Wortwolke'],['rank','Rangliste'],['bars','Balken']].map(([k,v])=>`<button data-app-mode="${k}" aria-pressed="${appMode===k}">${v}</button>`).join('')}</div><div id="app-chart">${appsView(data)}</div><div class="print-only">${data.wir.available?appTable(data.wir.apps):''}</div><p class="help">Unbekannte App-Namen werden vor der Veröffentlichung moderiert. Reflexionstexte erscheinen hier nie.</p><h3>JIM ${data.jim.dataset.study_year} · ${esc(data.jim.age_group)} Jahre</h3><p class="help">Die fünf veröffentlichten wichtigsten Apps dieser Altersgruppe. Bis zu drei offene Nennungen, Basis insgesamt n = 1.135 mit eigenem Smartphone. Nicht aufgeführte Apps sind keine Nullwerte.</p>${refs.length?`<div class="table-scroll"><table><thead><tr><th>App</th><th>JIM · %</th></tr></thead><tbody>${refs.map(r=>`<tr><td>${esc(r.item_id)}</td><td>${fmt(Number(r.percentage))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="help">Für diesen Vergleich liegt noch kein Referenzwert vor.</p>'}</section>`;}
function plusCard(jim){const p=jim.context_study;if(!p)return '';return `<section class="card soft"><p class="eyebrow">Weiterdenken mit JIMplus</p><h2>${esc(p.title)}</h2><p>${esc(p.population)}</p><p class="help">Alle folgenden Werte: ${esc(p.age_group)} Jahre. Die Aussagen wurden hier sinngemäß zusammengefasst.</p><div class="compare-grid no-own">${p.cards.map(c=>`<div class="compare-cell ref"><strong>${fmt(c.percentage)} %</strong><h3>${esc(c.text)}</h3><p>${esc(c.prompt)}</p><a href="${esc(p.source)}#page=${c.page}" target="_blank" rel="noopener noreferrer">Quelle · Seite ${c.page}</a></div>`).join('')}</div><p class="help">Diese Impulse ergänzen die Diskussion. Sie bewerten weder dein ICH noch eure Klasse.</p></section>`;}
function resultsContent(data){return `<p class="live-stamp">Stand: ${date(data.as_of)} · <strong>${data.wir.n} vollständige Abgaben</strong> · automatische Aktualisierung alle 8 Sekunden</p>${!data.wir.available?'<div class="empty"><h2>Noch nicht genügend Ergebnisse.</h2><p>WIR erscheint ab fünf vollständigen Abgaben.</p></div>':''}<div class="results-title"><h2>Sieben Blicke auf euren Alltag.</h2><div class="tabs no-print"><button data-detail="0" aria-pressed="${!detail}">Kurzansicht</button><button data-detail="1" aria-pressed="${detail}">Detailansicht</button></div></div><div class="legend">${[4,3,2,1].map((k,i)=>`<span><i style="background:${['#881337','#b64c67','#dba0af','#f2dce2'][i]}"></i>${answers[k]}</span>`).join('')}</div>${dims.map((_,i)=>itemCard(i,data)).join('')}${screenCard(data)}${appsCard(data)}${plusCard(data.jim)}${data.response?.reflection?`<section class="card"><span class="badge ich">DEINE PRIVATE REFLEXION</span><p style="white-space:pre-wrap;margin-top:15px">${esc(data.response.reflection)}</p></section>`:''}<section class="card soft"><h2>Was lesen wir aus den Ergebnissen?</h2><p>Welche Unterschiede fallen euch auf? Welche Rolle spielen Ferien, Schule oder Praktikum? Was erklärt eine Zahl – und was bleibt offen?</p><p class="help">Ein Klassenvergleich ist keine repräsentative Studie. JIM ist eine Vergleichsgruppe und kein Grenzwert. Der Rückblick auf euren Beobachtungszeitraum unterscheidet sich von der Erhebungssituation der JIM-Studie.</p>${link('projects','Wie geht es weiter?','button secondary no-print')}</section><p class="reference-note">JIM ${data.jim.dataset.study_year} · gewählte Altersgruppe ${esc(data.jim.age_group)} (sieben Aussagen: Gesamtgruppe 12–19, sofern gekennzeichnet) · Version ${esc(data.jim.dataset.source_version)}<br>Basis: ${esc(data.jim.dataset.population)}<br>Quelle: <a href="${esc(data.jim.dataset.source)}" target="_blank" rel="noopener noreferrer">${esc(data.jim.dataset.source)}</a><br>${data.jim.dataset.verified?'Nur hinterlegte, geprüfte Referenzwerte werden angezeigt.':'Keine verifizierten altersbezogenen Referenzzahlen in dieser Version hinterlegt.'}<br>Experimentdaten: anonyme Selbstauskunft der Klasse · Ergebnisstand ${date(data.as_of)}.</p>`;}
function bindResults(data){$$('[data-detail]').forEach(b=>b.onclick=()=>{detail=b.dataset.detail==='1';$('#result-content').innerHTML=resultsContent(data);bindResults(data);});$$('[data-app-mode]').forEach(b=>b.onclick=()=>{appMode=b.dataset.appMode;$('#app-chart').innerHTML=appsView(data);$$('[data-app-mode]').forEach(el=>el.setAttribute('aria-pressed',el===b));});}
let latestResult;
async function resultPage(gen){const v=view(),route=v==='result'?'results':v==='class'?'public':'admin',t=v==='admin'?adminToken():v==='result'?ownToken():'';if(v!=='class'&&!t){if(v==='result')go('join',code());else throw new Error('Bitte öffne den gesicherten Verwaltungslink dieser Klasse.');return;}const load=()=>api(route,{token:t,code:code()});const data=await load();if(gen!==generation)return;latestResult=data;watchClass(data.class);setMain(`<div class="heading-row"><div><p class="eyebrow">${v==='admin'?'Lehrkraft-Cockpit':v==='class'?'Unsere Klasse':'Deine Auswertung'} · ${esc(data.class.label||data.class.code)}</p><h1>${v==='result'?'ICH – WIR – JIM':'WIR – JIM'}</h1><p class="muted">${v==='result'?'Dein ICH steht fest. Euer WIR wächst weiter.':'Gemeinsam beobachten. Gemeinsam verstehen.'}</p></div><div class="actions no-print no-present"><button class="button secondary small" id="print">${v==='result'?'ICH – WIR – JIM drucken':'Klassenbericht drucken'}</button>${v!=='result'?'<button class="button small" id="present">Präsentationsmodus</button>':''}</div></div>${v==='admin'?adminPanel(data):''}<div id="poll-status" role="status"></div><div id="result-content">${resultsContent(data)}</div>${v==='result'?'<div class="actions no-print"><button class="button secondary" id="forget">Zugang auf diesem Gerät entfernen</button><span class="help">Der anonyme Datensatz bleibt bis zum Klassenablauf erhalten.</span></div>':''}<button class="button secondary exit-present" id="exit-present">Präsentation beenden</button>`);watchClass(data.class);bindResults(data);$('#print').onclick=()=>window.print();if($('#present'))$('#present').onclick=()=>document.body.classList.add('present');$('#exit-present').onclick=()=>document.body.classList.remove('present');if($('#forget'))$('#forget').onclick=()=>{if(confirm('Persönlichen Zugang von diesem Gerät entfernen? Ohne diesen Zugang kannst du dein ICH nicht erneut öffnen.')){storage('local','handy:'+code(),null);go('home');}};if(v==='admin')bindAdmin(data);
 polling=setInterval(async()=>{if(document.hidden||busy||printing)return;try{const next=await load();if(gen!==generation)return;latestResult=next;watchClass(next.class);$('#poll-status').textContent='';const openState=$$('details',$('#result-content')).map(el=>el.open);const active=document.activeElement;const focusDetail=active?.dataset.detail,focusApp=active?.dataset.appMode;$('#result-content').innerHTML=resultsContent(next);bindResults(next);$$('details',$('#result-content')).forEach((el,i)=>el.open=!!openState[i]);if(focusDetail!==undefined)$('[data-detail="'+focusDetail+'"]')?.focus({preventScroll:true});if(focusApp!==undefined)$('[data-app-mode="'+focusApp+'"]')?.focus({preventScroll:true});if(v==='admin'){$('#participant-count').textContent=next.class.n;$('#expires-label').textContent=date(next.class.expires_at);$('#moderation').innerHTML=moderation(next);bindModeration();}}catch(e){if(gen!==generation)return;if(e.status===410)expire();else if(e.status===403){clearInterval(polling);$('#result-content').innerHTML='<div class="empty">Die Klassenansicht ist derzeit nicht freigegeben.</div>';}else $('#poll-status').innerHTML='<p class="banner">Die Live-Verbindung ist unterbrochen. Angezeigt wird der letzte erfolgreiche Stand.</p>'; }},8000);
}
function adminPanel(data){const c=data.class;return `<section class="card no-print no-present"><div class="access-grid"><div><p class="eyebrow">Euer Klassencode</p><p class="code">${esc(c.code)}</p><p class="help">Diesen Code oder QR-Code an die Klasse weitergeben.</p><div class="actions"><button class="button secondary small" id="copy-join">Teilnahmelink kopieren</button><button class="button secondary small" id="copy-admin">Verwaltungslink sichern</button></div></div><div class="qr" id="qr"></div></div><div class="banner" style="margin:22px 0 0">Der Verwaltungslink ist dein einziger Adminzugang. Bitte privat sichern und nicht an die Klasse weitergeben.</div></section><div class="metrics no-present no-print"><div class="metric"><span>Abgeschlossen</span><strong><b id="participant-count">${c.n}</b>${c.expected?' / '+c.expected:''}</strong><small>Nur endgültige Abgaben zählen.</small></div><div class="metric"><span>Restlaufzeit</span><strong data-remaining></strong><small>Start: 270 Minuten</small></div><div class="metric"><span>Automatische Löschung</span><strong style="font-size:1.1rem" id="expires-label">${date(c.expires_at)}</strong><small>Spätestens ${date(c.max_expires_at)}</small></div></div><section class="card admin-controls no-print no-present"><h2>Klasse verwalten</h2><p>${c.weeks.length} Beobachtungswochen · ${c.weeks.map(w=>`W${w.week_number}: ${esc(weekTypes[w.context_type]||w.label)}`).join(' · ')}</p><div class="actions admin-actions"><button class="button secondary" id="publish">${c.public?'Klassenansicht schließen':'Klassenansicht freigeben'}</button>${link('class','Öffentliche Klassenansicht öffnen','button secondary',c.code)}</div><p class="help">Öffne die öffentliche Ansicht erst für die gemeinsame Besprechung. Deine persönliche Verwaltungsansicht ist unabhängig davon verfügbar.</p><details><summary>Laufzeit um sieben Tage verlängern</summary><p class="help">Benötigt einen aktiven Lehrkräfteschlüssel des Betreibers. Er vermittelt keinen Zugang zu anderen Klassen. Maximal 28 Tage ab Erstellung.</p><form id="extend-form" class="stack"><label for="teacher-key">Lehrkräfteschlüssel</label><input id="teacher-key" type="password" autocomplete="off" maxlength="64" required><button class="button">Um 7 Tage verlängern</button></form>${boot.contact_email?`<p class="help">Schlüssel anfragen: <a href="mailto:${esc(boot.contact_email)}">${esc(boot.contact_email)}</a></p>`:''}</details><details><summary>Unbekannte App-Begriffe moderieren</summary><p class="help">Nur unzugeordnete Begriffe, keine einzelnen Antworten. Keine Namen oder beleidigenden Inhalte freigeben.</p><div id="moderation">${moderation(data)}</div></details><details><summary>Klasse vorzeitig löschen</summary><p>Alle Antworten, Entwürfe und Zugänge werden unwiderruflich gelöscht.</p><button class="button danger" id="delete-class">Klasse endgültig löschen</button></details></section>`;}
function moderation(data){if(data.class.n<5)return '<p class="help">Verfügbar ab fünf vollständigen Abgaben.</p>';return data.terms.length?data.terms.map(t=>`<div class="moderation-row"><span>${esc(t.normalized)} ${t.status==='blocked'?'(gesperrt)':''}</span><button class="button secondary small" data-moderate="${t.id}" data-status="approved">Freigeben</button>${t.status!=='blocked'?`<button class="button secondary small" data-moderate="${t.id}" data-status="blocked">Sperren</button>`:''}</div>`).join(''):'<p class="help">Keine offenen Begriffe.</p>';}
function bindModeration(){$$('[data-moderate]').forEach(b=>b.onclick=()=>action(async()=>{await api('moderate',{token:adminToken(),data:{id:Number(b.dataset.moderate),status:b.dataset.status}});const r=await api('admin',{token:adminToken()});latestResult=r;$('#moderation').innerHTML=moderation(r);bindModeration();$('#result-content').innerHTML=resultsContent(r);bindResults(r);},b));}
async function copy(text){try{await navigator.clipboard.writeText(text);notice('Link kopiert.');}catch{prompt('Diesen Link kopieren:',text);}}
function bindAdmin(data){const base=boot.base_url+'/',join=base+'?view=join&code='+data.class.code;const qr=qrcode(0,'M');qr.addData(join);qr.make();$('#qr').innerHTML=qr.createSvgTag({cellSize:4,margin:16,scalable:true});$('#qr svg').setAttribute('role','img');$('#qr svg').setAttribute('aria-label','QR-Code zum Beitritt zur Klasse');$('#copy-join').onclick=()=>copy(join);$('#copy-admin').onclick=()=>copy(base+'?view=admin&code='+data.class.code+'#admin='+adminToken());$('#publish').onclick=e=>action(async()=>{await api('publish',{token:adminToken(),data:{public:!latestResult.class.public}});await render();},e.currentTarget);$('#extend-form').onsubmit=e=>{e.preventDefault();action(async()=>{const key=$('#teacher-key').value.trim();const r=await api('extend',{token:adminToken(),data:{key}});$('#teacher-key').value='';watchClass(r.class);$('#expires-label').textContent=date(r.class.expires_at);notice('Die Laufzeit wurde verlängert.');},e.submitter);};$('#delete-class').onclick=e=>{if(confirm('Diese Klasse und alle zugehörigen Daten jetzt endgültig löschen? Es gibt keine Wiederherstellung.'))action(async()=>{await api('delete',{token:adminToken(),data:{}});expire();},e.currentTarget);};bindModeration();}
function infoPage(){const steps=[['Beobachten','Dein Alltag. Dein Heft.','Standard: sechs Wochen. Eure Lehrkraft kann 1–52 Wochen und Ferien, Schule, Praktikum oder eigene Kontexte festlegen. Notiere täglich die abgelesene Bildschirmzeit, bis zu drei für dich wichtige Apps und eine rotierende Reflexion. Vergessenes nicht erfinden. Das Heft bleibt privat.'],['ICH','Du ziehst Bilanz.','Sieh dir im Heft die Beobachtungen zu jeder der sieben Fragen an. Entscheide selbst, wie die allgemeine Aussage insgesamt zu dir passt. Kein rechnerischer Mittelwert der Antwortkategorien. Übertragen werden sieben Antworten, Wochenmittel der Bildschirmzeit, bis zu drei Apps und optional eine private Reflexion.'],['WIR','Eine Klasse. Viele Perspektiven.','Nur endgültige Abgaben zählen. Ab fünf vollständigen Antworten erscheinen anonyme Klassenwerte und aktualisieren sich automatisch. Dein ICH bleibt unverändert. Lehrkräfte sehen keine einzelnen Antworten. Unbekannte App-Namen werden vor der öffentlichen Anzeige moderiert.'],['JIM','Über die Klasse hinausblicken.','JIM 2025 liefert Vergleichsdaten. Alterswerte gibt es für Bildschirmzeit und Apps; die sieben Aussagen sind als Gesamtgruppe 12–19 gekennzeichnet. JIMplus 2026 ergänzt Reflexionsimpulse für 14–17-Jährige. Andere Stichproben und Zeiträume: kein Grenzwert und keine Bewertung.'],['Reflektieren','Was steckt hinter den Zahlen?','Besprecht Unterschiede und Gemeinsamkeiten. Welche Rolle spielen Ferien, Schule oder Praktikum? Was hilft dir, was belastet dich? Nutzt Diagramme, App-Wortwolken und den druckbaren ICH–WIR–JIM-Bericht.'],['Gestalten','Das Handy als Werkzeug.','Erprobt digitale Medien in einem Fachprojekt. Vergleicht den digitalen Weg mit einer analogen Alternative. Erstellt ein fachliches Lernprodukt und eine Projektkarte zu Mehrwert, Grenzen und eurem Fazit. Projekte bleiben von Umfrageantworten getrennt.']];setMain(`<article class="how-page"><p class="eyebrow">So funktioniert Medienblick</p><h1>Erst beobachten.<br><span class="accent">Dann bewusst gestalten.</span></h1><p class="lead">Ein privates Heft, eine anonyme Auswertung und neue Ideen für euren Medienalltag.</p><p class="help">Tippe auf einen Schritt für die kurze Erklärung.</p><ol class="flow-map">${steps.map(([title,sub,body],i)=>`<li><details class="flow-step"><summary><span class="flow-number">${String(i+1).padStart(2,'0')}</span><span><strong>${title}</strong><span>${sub}</span></span><b aria-hidden="true">+</b></summary><p>${body}</p></details></li>`).join('')}</ol><div class="how-facts"><div><strong>Privat</strong><span>Deine Tagesbeobachtungen bleiben im Heft.</span></div><div><strong>Anonym</strong><span>Keine Schülerkonten, Namen oder Gerätefingerprints.</span></div><div><strong>Temporär</strong><span>270 Minuten aktiv. Mit Lehrkräfteschlüssel verlängerbar, höchstens 28 Tage.</span></div></div><details class="how-teacher"><summary>Für Lehrkräfte: in drei Schritten starten</summary><p><strong>1.</strong> Klasse erstellen, Zeitraum und Wochenarten wählen.<br><strong>2.</strong> Klassencode oder QR-Code nach der Beobachtungszeit teilen.<br><strong>3.</strong> Gemeinsam auswerten, diskutieren und Klassenbericht drucken.</p><p class="help">Verwaltungslink sicher aufbewahren. Nach Ablauf werden Klasse und Antworten gelöscht. Teilnahme ist freiwillig; Medienblick ist kein Sucht-Screening.</p></details><div class="actions">${link('create','Klasse erstellen','button')}${link('projects','Projektideen entdecken','button secondary')}${link('privacy','Datenschutz im Detail')}</div></article>`);}
function privacyPage(){setMain(`<article class="article"><p class="eyebrow">Datenschutz & Kontakt</p><h1>Dein Heft gehört dir.</h1><section class="card"><h2>Was diese App speichert</h2><p>Sieben Abschlussantworten, freiwillige Mittelwerte pro Beobachtungswoche, bis zu drei App-Nennungen und gegebenenfalls eine private Reflexion. Hinzu kommen zufällige Zugangsschlüssel in gehashter Form und der Status deiner Teilnahme. Tageswerte aus der Rechenhilfe werden nicht übertragen.</p><h2>Wer was sehen kann</h2><p>Mit deinem persönlichen Zugang siehst du dein ICH. Lehrkraft und freigegebene Klassenansicht zeigen nur Aggregate ab mindestens fünf Abgaben. Reflexionen sind ausschließlich persönlich sichtbar. Bitte in offenen Feldern keine Namen oder anderen persönlichen Angaben eintragen.</p><h2>Dein Gerät</h2><p>Ein technisch notwendiges Sitzungscookie schützt Anfragen. Ein zufälliger Teilnahmezugang liegt lokal auf deinem Gerät und ermöglicht das Fortsetzen. Ein Verwaltungszugang bleibt im Sitzungsspeicher der Lehrkraft. Es gibt kein Tracking, keine Werbung und keine Analyse-Dienste. Auf gemeinsamen Geräten den persönlichen Zugang nach der Auswertung entfernen.</p><h2>Löschung</h2><p>Nach 270 Minuten endet die Klasse, sofern die Lehrkraft sie nicht verlängert. Die absolute Obergrenze beträgt 28 Tage. Bei Ablauf sind Daten sofort nicht mehr zugänglich und werden beim Zugriff oder durch den Löschlauf entfernt. Browser-Zugänge werden bei erkannter Löschung bereinigt. Offline gespeicherte lokale Zugänge werden beim nächsten Öffnen geprüft.</p><h2>Freiwilligkeit und Grenzen</h2><p>Du kannst vor der Abgabe aufhören. Es gibt keine automatische Bewertung und kein Sucht-Screening. Die endgültige Abgabe kann nicht verändert werden. Die Lehrkraft kann die gesamte Klasse vorzeitig löschen. Klassenwerte können bei Beobachtung einzelner Live-Abgaben Rückschlüsse ermöglichen; besprecht Ergebnisse gemeinsam nach der Sammlung.</p><p class="help">Die Webanwendung verarbeitet keine IP-Adressen zur Identifikation. Für technische Protokolle, Hosting, Sicherungen und die rechtlichen Angaben ist der Betreiber verantwortlich. Diese müssen für den tatsächlichen Schulbetrieb passend eingerichtet sein.</p></section><section class="card"><h2>Betreiber und Kontakt</h2><p style="white-space:pre-wrap">${esc(boot.legal_notice)}</p>${boot.contact_email?`<p><a href="mailto:${esc(boot.contact_email)}">${esc(boot.contact_email)}</a></p>`:'<p class="help">Die Betreiber-Kontaktadresse ist noch nicht eingerichtet.</p>'}</section></article>`);}
function projectPage(){const ideas=[['Mathematik','Bildschirmzeit statistisch untersuchen','Untersucht an einem freiwilligen, nicht personenbezogenen Beispieldatensatz, wie Mittelwert, Median und Diagrammwahl die Interpretation verändern.','Statistische Untersuchung','Tabellenkalkulation und Diagramme'],['Mathematik','Schulgelände vermessen','Vergleicht eine trigonometrische Höhenmessung per Smartphone mit Maßband und selbst gebautem Peilgerät.','Messprotokoll','Winkelmessung und Dokumentation'],['Chemie','Ein Experiment verständlich erklären','Erstellt zu einem freigegebenen Unterrichtsexperiment eine Erklärung und vergleicht Video und gezeichnete Bildfolge.','Erklärvideo und fachliches Protokoll','Aufnahme, Schnitt und Zeitlupe'],['Chemie','Farben als Messsignal','Untersucht unter Anleitung, ob Fotos einer sicheren Farbreihe einen nachvollziehbaren Vergleich ermöglichen.','Untersuchungsbericht','Kamera unter konstanten Lichtbedingungen'],['Informatik','Wie beeinflussen Benachrichtigungen Aufmerksamkeit?','Entwerft einen lokalen Prototyp, mit dem verschiedene Benachrichtigungseinstellungen ohne echte persönliche Daten verglichen werden.','Programm oder Prototyp','Interfacegestaltung und lokale Simulation'],['Informatik','Was verrät eine App-Berechtigung?','Vergleicht Berechtigungen ausgewählter Apps und erklärt deren fachliche Bedeutung anhand fiktiver Nutzungssituationen.','Digitale Ausstellung','Recherche und nachvollziehbare Dokumentation'],['Deutsch','Eine Geschichte in zwei Medien','Setzt eine kurze eigene Geschichte als Hörbeitrag und als Text um. Analysiert die unterschiedlichen Wirkungen.','Podcast und Textvergleich','Tonaufnahme und Schnitt'],['Biologie','Arten erkennen und Ergebnisse prüfen','Vergleicht eine Bestimmungs-App mit einem analogen Bestimmungsschlüssel. Prüft unsichere Treffer fachlich.','Bestimmungsdokumentation','Kamera und Bestimmungshilfe']];let active=0;setMain(`<article><p class="eyebrow">Die Medienblick-Projektwerkstatt</p><h1>Vom Bildschirm<br><span class="accent">zum Lernwerkzeug.</span></h1><p class="lead">Acht Ideen zum Durchblättern. Immer mit einer Frage: Was bringt der digitale Weg – und was kann die analoge Alternative?</p><section class="project-carousel" aria-label="Projektideen" aria-roledescription="Karussell"><div class="carousel-toolbar"><button class="button secondary" id="project-prev" aria-label="Vorheriges Projekt">←</button><span id="project-count" role="status" aria-live="polite"></span><button class="button secondary" id="project-next" aria-label="Nächstes Projekt">→</button></div><div id="project-slide"></div><div class="project-dots" aria-label="Projekt auswählen">${ideas.map((a,i)=>`<button data-project="${i}" aria-label="Projekt ${i+1}: ${esc(a[1])}">${i+1}</button>`).join('')}</div></section><div class="how-facts"><div><strong>Fachliches Produkt</strong><span>Video, Untersuchung, Podcast oder Dokumentation.</span></div><div><strong>Gemeinsame Projektkarte</strong><span>Thema, Werkzeug, Ergebnis, analoge Alternative, Mehrwert, Grenzen und Fazit.</span></div><div><strong>Gemeinsam abstimmen</strong><span>Beispiele zur Planung. Plätze, Bewertung und Freigabe klärt eure Fachlehrkraft.</span></div></div><p class="help">Die Projektwerkstatt ist von euren anonymen Antworten getrennt. Hier werden keine Projektwahlen oder Arbeitsergebnisse gespeichert.</p></article>`);const show=()=>{const [subject,title,desc,product,media]=ideas[active];const extras=active===0?'<a href="assets/material/statistik-beispieldaten.csv" download>Erfundene Beispieldaten (CSV) ↓</a>':active===2?'<a href="https://harzenetter.eu/assets/Arbeitsprotokoll_Lernvideos.pdf" target="_blank" rel="noopener noreferrer">Arbeitsprotokoll Lernvideos (PDF) ↗</a>':active===6?'<a href="https://harzenetter.eu/assets/Arbeitsprotokoll_Podcasts.pdf" target="_blank" rel="noopener noreferrer">Arbeitsprotokoll Podcasts (PDF) ↗</a>':'';$('#project-slide').innerHTML=`<div class="project-slide" role="group" aria-roledescription="Folie" aria-label="${active+1} von ${ideas.length}"><figure><img src="assets/material/projekt-${active+1}.svg" alt="${esc(title)}: schematische Beispielgrafik"><figcaption>Beispielmaterial · eigens für Medienblick erstellt</figcaption></figure><div class="project-copy"><span class="study-tag">${esc(subject)}</span><h2>${esc(title)}</h2><p>${esc(desc)}</p><dl><dt>Lernprodukt</dt><dd>${esc(product)}</dd><dt>Smartphone-Einsatz</dt><dd>${esc(media)}</dd></dl><div class="project-material"><a class="button" href="assets/material/projekt-${active+1}.html" target="_blank" rel="noopener noreferrer">Projektblatt öffnen ↗</a><a href="assets/material/projekt-${active+1}.svg" download>Beispielgrafik herunterladen ↓</a>${extras}</div></div></div>`;$('#project-count').textContent=`Projekt ${active+1} von ${ideas.length}`;$$('[data-project]').forEach(b=>b.setAttribute('aria-current',Number(b.dataset.project)===active?'true':'false'));};const move=delta=>{active=(active+delta+ideas.length)%ideas.length;show();};$('#project-prev').onclick=()=>move(-1);$('#project-next').onclick=()=>move(1);$$('[data-project]').forEach(b=>b.onclick=()=>{active=Number(b.dataset.project);show();});$('.project-carousel').onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(e.key==='ArrowRight'?1:-1);}};let touchX=null;$('#project-slide').addEventListener('touchstart',e=>{touchX=e.touches[0].clientX;},{passive:true});$('#project-slide').addEventListener('touchend',e=>{if(touchX!==null&&Math.abs(e.changedTouches[0].clientX-touchX)>65)move(e.changedTouches[0].clientX<touchX?1:-1);touchX=null;},{passive:true});show();}
window.addEventListener('popstate',render);window.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('present');});
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||a.target)return;const u=new URL(a.href,location.href);if(u.origin===location.origin&&u.pathname===location.pathname&&u.searchParams.has('view')){e.preventDefault();if(view()==='survey'&&currentResponse){clearTimeout(saveTimer);enqueueSave().then(()=>{history.pushState({},'',u.search);render();}).catch(()=>{});}else{history.pushState({},'',u.search);render();}}});
let printing=false,printDetails=[];window.addEventListener('beforeprint',()=>{printing=true;printDetails=$$('details',$('#result-content')||$('#main')).map(el=>({el,open:el.open}));printDetails.forEach(x=>x.el.open=true);});window.addEventListener('afterprint',()=>{printing=false;printDetails.forEach(x=>x.el.open=x.open);});
async function init(){try{const frag=new URLSearchParams(location.hash.slice(1));const t=frag.get('admin');if(t&&/^[a-f0-9]{64}$/.test(t)){storage('session','handy-admin',{token:t});history.replaceState({},'',location.pathname+location.search);}boot=await api('bootstrap');try{for(let i=localStorage.length-1;i>=0;i--){const k=localStorage.key(i);if(!k?.startsWith('handy:'))continue;const v=storage('local',k);if(v&&Date.parse(v.expires_at)<=Date.now()){try{const r=await api('class',{code:k.slice(6)});v.expires_at=r.class.expires_at;storage('local',k,v);}catch(e){if(e.status===404||e.status===410)storage('local',k,null);}}}}catch{}await render();}catch(e){setMain(`<div class="empty"><h1>Noch nicht erreichbar.</h1><p>${esc(e.message)}</p><button class="button" id="reload">Erneut versuchen</button></div>`);$('#reload').onclick=()=>location.reload();}}init();
